import React, { Component } from "react";
import moment from "moment";
import WebServicesManager from "../../WebServicesManager/WebServicesManager";
import {Button,Modal,
    Grid,
    Row,
    Col,
    FormGroup,
    ControlLabel,
    FormControl,
    HelpBlock,
    DropdownButton,
    MenuItem
} from "react-bootstrap";
import Autocomplete from "react-autocomplete";


export class UserCard extends Component {
    WebServicesManager = new WebServicesManager();
    constructor(props){
        super(props);
        this.state={
            items:[],
            showModal:false,
            firstName:this.props.firstName,
            surName:this.props.surName,
            email:this.props.email,
            contactEmail:this.props.contactEmail,
            secondEmail:this.props.secondEmail,
            secondPhone:this.props.secondPhone,
            password:this.props.password,
            dob:this.props.dob,
            phone:this.props.phone,
            address:this.props.address,
            city:this.props.city,
            zip:this.props.zip,
            lat:this.props.lat,
            long:this.props.long,
            addressError:"",
            gender:this.props.gender,
            complement:this.props.complement,
            highWayCodeDate:this.props.highWayCodeDate,
            neph:this.props.neph,
            frontIDPhoto:"",
            backIDPhoto:"",
            frontIdPathError:this.props.frontIDPhoto,
            backIdPathError:this.props.backIDPhoto,
            banStatus:"",
            banDate:"",
        };
    }

    componentWillMount(){
        this.WebServicesManager.getApiWithParamCall(
        {
            endPoint: "Profile/GetProfileByPersonalId",
            dataToFetch: this.props.id
        },
        (statusCode,response)=>{
            this.setState({
                banStatus:response.banStatus !== null?response.banStatus:"",
                banDate:response.banDate !== null ? response.banDate : ""
            });
        });
    }


    handleFrontFileSelect = e =>{
        if (
        e.target.files[0] !== "" ||
        e.target.files[0] !== null ||
        e.target.files[0] !== undefined
        ) {
        this.setState({frontIDPhoto:e.target.files[0].name});
        const imagedata = e.target.files[0];
        const Picture = new FormData();
        Picture.append("file", imagedata);
        this.WebServicesManager.postApiImageCall(
            {
            endPoint: "Personal/UploadProfileImage",
            dataToInsert: Picture
            },
            (statusCode, response) => {
            this.setState({
                frontIDPhoto: response
            });
            });
        }else{
        console.log("file is null");    
        }
    }
    handleBackFileSelect = e =>{
        if (
        e.target.files[0] !== "" ||
        e.target.files[0] !== null ||
        e.target.files[0] !== undefined
        ) {
        this.setState({backIDPhoto:e.target.files[0].name});
        const imagedata = e.target.files[0];
        const Picture = new FormData();
        Picture.append("file", imagedata);
        this.WebServicesManager.postApiImageCall(
        {
            endPoint: "Personal/UploadProfileImage",
            dataToInsert: Picture
        },
        (statusCode, response) => {
            this.setState({
            backIDPhoto: response
            });
        });
        }else{
        console.log("file is null");
        }
    }


    getAddress = e => {
        this.setState({ address: e.target.value });
        fetch(
          "https://api-adresse.data.gouv.fr/search/?q=" +
            e.target.value +
            "&type=street&autocomplete=1&limit=15"
        )
          .then(response => response.json())
          .then(responseJson => {
            console.log("res address",responseJson);
            var addressToSet = [];
            for (var i = 0; i < responseJson.features.length; i++) {
              addressToSet.push({
                id: i,
                label: responseJson.features[i].properties.label,
                city: responseJson.features[i].properties.city,
                PostalCode: responseJson.features[i].properties.postcode,
                lat: responseJson.features[0].geometry.coordinates[1],
                lng: responseJson.features[0].geometry.coordinates[0]
              });
            }
            if (addressToSet.length === responseJson.features.length) {
              this.setState({ items: addressToSet },()=>{
              console.log("Address to set",addressToSet,"state",this.state.items);
              });
            }
          })
          .catch(error => {
            console.error(error);
          });
      };
      SetAddress = item => {
        this.setState({ address: item });
        for (let i = 0; i < this.state.items.length; i++) {
          if (this.state.items[i].label === item) {
            var city = this.state.items[i].city;
            var zipCode = this.state.items[i].PostalCode;
            var lat = this.state.items[i].lat;
            var lng = this.state.items[i].lng;
            var newAddress = this.state.items[i].label.split(String(zipCode));
            this.setState({ address:newAddress[0],zip: zipCode, city: city, lat: lat, lng: lng });
            // this.validationCheckforAddress(this.state);
          }
        }
      };
    
    

    handleSave = () => {
        const data = {
            id:this.props.id,
            FirstName: this.state.firstName,
            SurName:this.state.surName,
            DOB: this.state.dob,
            PlaceOfBirth: this.props.placeOfBirth,
            gender:this.state.gender,
            FrontIDPhoto: this.state.frontIDPhoto===""?this.state.frontIdPathError:this.state.frontIDPhoto,
            BackIDPhoto: this.state.backIDPhoto===""?this.state.backIdPathError:this.state.backIDPhoto,
            address:this.state.address,
            Complement: this.state.complement,
            ZIP: this.state.zip,
            City:this.state.city,
            Photo:this.props.photo,
            Password:this.state.password,
            NEPH:this.state.neph,
            NoOfHrsWanted:this.props.noOfHrsWanted,
            Email:this.state.email,
            ContactEmail:this.state.contactEmail,
            Phone:this.state.phone,
            SecondEmail:this.state.secondEmail,
            SecondPhone:this.state.secondPhone,
            HighWayCodeDate:this.state.highWayCodeDate,
            Lat:this.state.lat,
            Long:this.state.long,
            Role:this.props.role,
            DrivingSchoolID:this.props.drivingSchoolID,
            RegistrationDate:this.props.RegistrationDate,
            documentTested:this.props.documentTested,
        }
        var datais = JSON.stringify(data);
        this.WebServicesManager.postApiCall({
            endPoint: "Personal/UpdatePersonal",
            dataToInsert: datais
        },
        (statusCode,response) => {  
            window.location.reload();
        });
    }

      
     
    handleFunc = (days) =>{
            var banTill = moment()
            .add(days, "days")
            .format();
            this.WebServicesManager.getApiWithParamCall(
            {
            endPoint:"Profile/GetProfileByPersonalId",
            dataToFetch: this.props.id
            },
            (statusCode, responcedata) =>
            {   
                const profiledata = {
                
                    id : responcedata.id,
                    role: responcedata.role,
                    PersonalInfoId: responcedata.personalInfoId,
                    DrivingLisenceInfoId: responcedata.drivingLisenceInfoId,
                    ExersiceAuthorizationInfoId: responcedata.exersiceAuthorizationInfoId,
                    VehicleDetailInfoId: responcedata.vehicleDetailInfoId,
                    VehicleInsuranceInfoId: responcedata.vehicleInsuranceInfoId,
                    DrivingSchoolInsuranceInfoId: responcedata.drivingSchoolInsuranceInfoId,
                    TechnicalControlInfoId: responcedata.technicalControlInfoId,
                    BusinessInfoId: responcedata.businessInfoId,
                    InsuranceCompanyInfoId: responcedata.insuranceCompanyInfoId,
                    DrivingSchoolIdentityInfoId: responcedata.drivingSchoolIdentityInfoId,
                    DrivingSchoolApprovalInfoId: responcedata.drivingSchoolApprovalInfoId,
                    DrivingSchoolManagerInfoId: responcedata.drivingSchoolManagerInfoId,
                    DrivingSchoolVehiclesInfoId: responcedata.drivingSchoolVehiclesInfoId,
                    DrivingSchoolInstructorInfoId: responcedata.drivingSchoolInstructorInfoId,
                    Lat: responcedata.lat,
                    Long: responcedata.long,
                    Status: responcedata.status,
                    BanStatus: "Ban",
                    BanDate: banTill,
                    
                }
                var dataTo = JSON.stringify(profiledata);
                this.WebServicesManager.postApiCall(
                    {
                        endPoint:"Profile/UpdateProfile",
                        dataToInsert:dataTo
                    },
                    (statusCode, response) =>
                    {
                     console.log("update",response);
                     window.location.reload();   
                    }
                );
            }
            )
    }


    handlefuntUnban = () =>{
      
        this.WebServicesManager.getApiWithParamCall(
        {
        endPoint:"Profile/GetProfileByPersonalId",
        dataToFetch: this.props.id
        },
        (statusCode, resp) =>
        {   
            const profiledataUnban = {
            
                id : resp.id,
                role: resp.role,
                PersonalInfoId: resp.personalInfoId,
                DrivingLisenceInfoId: resp.drivingLisenceInfoId,
                ExersiceAuthorizationInfoId: resp.exersiceAuthorizationInfoId,
                VehicleDetailInfoId: resp.vehicleDetailInfoId,
                VehicleInsuranceInfoId: resp.vehicleInsuranceInfoId,
                DrivingSchoolInsuranceInfoId: resp.drivingSchoolInsuranceInfoId,
                TechnicalControlInfoId: resp.technicalControlInfoId,
                BusinessInfoId: resp.businessInfoId,
                InsuranceCompanyInfoId: resp.insuranceCompanyInfoId,
                DrivingSchoolIdentityInfoId: resp.drivingSchoolIdentityInfoId,
                DrivingSchoolApprovalInfoId: resp.drivingSchoolApprovalInfoId,
                DrivingSchoolManagerInfoId: resp.drivingSchoolManagerInfoId,
                DrivingSchoolVehiclesInfoId: resp.drivingSchoolVehiclesInfoId,
                DrivingSchoolInstructorInfoId: resp.drivingSchoolInstructorInfoId,
                Lat: resp.lat,
                Long: resp.long,
                Status: resp.status,
                BanStatus: "",
                BanDate: "",
                
            }
            var dataTo = JSON.stringify(profiledataUnban);
            this.WebServicesManager.postApiCall(
                {
                    endPoint:"Profile/UpdateProfile",
                    dataToInsert:dataTo
                },
                (statusCode, response) =>
                {
                 console.log("update",response);
                 window.location.reload();   
                }
            );
        }
        )
}

        handlefuntDeActive = () =>{
            // debugger;
            this.WebServicesManager.getApiWithParamCall(
            {
            endPoint:"Profile/GetProfileByPersonalId",
            dataToFetch: this.props.id
            },
            (statusCode, resp) =>
            {   
                const profiledataUnban = {
                
                    id : resp.id,
                    role: resp.role,
                    PersonalInfoId: resp.personalInfoId,
                    DrivingLisenceInfoId: resp.drivingLisenceInfoId,
                    ExersiceAuthorizationInfoId: resp.exersiceAuthorizationInfoId,
                    VehicleDetailInfoId: resp.vehicleDetailInfoId,
                    VehicleInsuranceInfoId: resp.vehicleInsuranceInfoId,
                    DrivingSchoolInsuranceInfoId: resp.drivingSchoolInsuranceInfoId,
                    TechnicalControlInfoId: resp.technicalControlInfoId,
                    BusinessInfoId: resp.businessInfoId,
                    InsuranceCompanyInfoId: resp.insuranceCompanyInfoId,
                    DrivingSchoolIdentityInfoId: resp.drivingSchoolIdentityInfoId,
                    DrivingSchoolApprovalInfoId: resp.drivingSchoolApprovalInfoId,
                    DrivingSchoolManagerInfoId: resp.drivingSchoolManagerInfoId,
                    DrivingSchoolVehiclesInfoId: resp.drivingSchoolVehiclesInfoId,
                    DrivingSchoolInstructorInfoId: resp.drivingSchoolInstructorInfoId,
                    Lat: resp.lat,
                    Long: resp.long,
                    Status: resp.status,
                    BanStatus: "DeActive",
                    BanDate: "",
                    
                }
                // debugger;
                var dataTo = JSON.stringify(profiledataUnban);
                this.WebServicesManager.postApiCall(
                    {
                        endPoint:"Profile/UpdateProfile",
                        dataToInsert:dataTo
                    },
                    (statusCode, response) =>
                    {
                    window.location.reload();   
                    }
                );
            }
            )
        }
    render() {
        return (
            <div className="card card-user">
                <div className="image">
                    <img src={this.props.bgImage} alt="..." />
                </div>
                <div className="content">
                    <div className="author">
                        {/* <a href="#pablo"> */}
                            <img
                                 className="avatar border-gray"
                                src={this.props.photo !=="" ?this.props.photo : "data:image/png;base64,"}
                                alt="..."
                            />  
                            <div className="content">
                                <h4 className="title">
                                    {this.props.firstName}
                                    <br />
                                    <small>{this.props.surName}</small>
                                    <hr/>
                                </h4>
                                <table className="table table-striped">
                                    <tbody>
                                        <tr>
                                            <th>Email</th>
                                            <td>{(this.state.contactEmail===""||this.state.contactEmail === null)?this.state.email:this.state.contactEmail}</td>
                                        </tr>
                                        <tr>
                                            <th>Date of Birth</th>
                                            <td>{moment(this.props.dob).format('DD MMM YYYY')}</td>
                                        </tr>
                                        <tr>
                                            <th>Address</th>
                                            <td>{this.props.address}</td>
                                        </tr>
                                        <tr>
                                            <th>City</th>
                                            <td>{this.props.city}</td>
                                        </tr>
                                        <tr>
                                            <th>Phone</th>
                                            <td>{this.props.phone}</td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        {/* </a> */}
                    </div>
                    <p className="description text-center" style={{fontWeight:'bold',fontSize:16}}>{this.props.role}</p>
                    {this.state.banDate!==""?<p className="text-center" style={{fontSize:10}}>Ban till: {moment(this.state.banDate).format("DD/MM/YYYY")}</p>:""}
                    <center>
                    <Button varient="primary" style={{marginLeft:10,marginTop:10}} onClick={()=>this.setState({showModal:true})}>Upadate Data</Button>
                   {this.state.banStatus === "" ? 
                   <DropdownButton
                        bsStyle="default"
                        title="Ban Student"
                        noCaret
                        id="dropdown-no-caret"
                        style={{fontSize:'14px',marginLeft:10,marginTop:10}}
                        >
                        <MenuItem
                            onClick={() => this.handleFunc(15)}
                            eventKey="1"
                        >
                            15 Days
                        </MenuItem>
                        <MenuItem onClick={()=>this.handleFunc(30)} eventKey="2">
                            30 Days
                        </MenuItem>
                    </DropdownButton>: 
                        this.state.banStatus !== "DeActive" ?
                        <> 
                        <Button varient="primary" style={{marginLeft:10,marginTop:10}} onClick={this.handlefuntUnban}>Un-Ban</Button>
                        </>
                        : ""
                     } 
                    {this.state.banStatus === "" && this.state.banStatus !=="Ban" ?
                    <Button varient="primary" style={{marginLeft:10,marginTop:10}} onClick={this.handlefuntDeActive}>De-Active</Button>:
                    this.state.banStatus !== "Ban" ?
                    <>
                    {/* <p>De-Activated</p>  */}
                    <Button varient="primary" style={{marginLeft:10,marginTop:10}} onClick={this.handlefuntUnban}>Re-active</Button>
                      </>
                      :""
                      }</center>
                </div>
                <hr />
                <div className="text-center">{this.props.socials}</div>
                <Modal
                    show={this.state.showModal}
                    onHide={()=>this.setState({showModal:false})}
                    backdrop="static"
                    keyboard={false}
                    size="xl"
                >
                    <Modal.Header closeButton>
                    <Modal.Title>Update Data</Modal.Title>
                    </Modal.Header>
                    <Modal.Body>
                    <div className="content">
                <Grid fluid>
                    <Row>
                        <Col md={12}>
                            <form>
                                <div className="clearfix" />
                                <div className="container-flex">
                                    <div>
                                        <div className="row">
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>First Name</ControlLabel>
                                                    <FormControl className="form-control"
                                                        value={this.state.firstName}  
                                                        onChange={(e) => { this.setState({ firstName: e.target.value }); }} 
                                                    />
                                                </FormGroup>
                                            </div>
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Sur Name</ControlLabel>
                                                    <FormControl className="form-control"
                                                        value={this.state.surName} 
                                                        onChange={(e) => { this.setState({ surName: e.target.value }); }}></FormControl>
                                                </FormGroup>
                                            </div>
                                        </div>
                                        {this.props.role !== "DrivingSchool"?
                                        <div className="row"> 
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>DOB</ControlLabel>
                                                    <FormControl className="form-control"
                                                        type="date"
                                                        value={moment(this.state.dob).format("YYYY-MM-DD")} 
                                                        onChange={(e) => { this.setState({ dob: e.target.value }); }} />
                                                </FormGroup>
                                            </div>
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Gender</ControlLabel>
                                                    <FormControl
                                                        componentClass="select"
                                                        name="gender"
                                                        value={this.state.gender}
                                                        onChange={e=>this.setState({gender:e.target.value})}
                                                        >
                                                        <option value="male">Male</option>
                                                        <option value="female">Female</option>
                                                        <option value="other">Other</option>
                                                        </FormControl>
                                                </FormGroup>
                                            </div>
                                        </div>:""}
                                        <div className="row">
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Email</ControlLabel>
                                                    <FormControl className="form-control"  
                                                    value={(this.state.contactEmail===""||this.state.contactEmail === null)?this.state.email:this.state.contactEmail} 
                                                    onChange={(e) => { this.setState({ contactEmail: e.target.value }); }}></FormControl>
                                                </FormGroup>
                                            </div>
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Phone</ControlLabel>
                                                    <FormControl className="form-control" maxLength={10}  onChange={(e) => { this.setState({ phone: e.target.value }); }}
                                                        value={this.state.phone} 
                                                        />
                                                </FormGroup>
                                            </div>
                                        </div>
                                        <div className="row">
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Second Email</ControlLabel>
                                                    <FormControl className="form-control"  
                                                    value={this.state.secondEmail} 
                                                    onChange={(e) => { this.setState({ secondEmail: e.target.value }); }}></FormControl>
                                                </FormGroup>
                                            </div>
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Second Phone</ControlLabel>
                                                    <FormControl className="form-control" maxLength={10}  onChange={(e) => { this.setState({ secondPhone: e.target.value }); }}
                                                        value={this.state.secondPhone} 
                                                        />
                                                </FormGroup>
                                            </div>
                                        </div>

                                        <div className="row">
                                            <Col md={6} className="address-in">
                                                <FormGroup>
                                                    <ControlLabel>
                                                    Address <span className="text-red"></span>
                                                    </ControlLabel>
                                                    <br />
                                                    <Autocomplete
                                                    items={this.state.items}
                                                    // shouldItemRender={(item, value) =>
                                                    //     item.label.toLowerCase().indexOf(value.toLowerCase()) > -1
                                                    // }
                                                    getItemValue={item => item.label}
                                                    renderItem={(item, highlighted) => (
                                                        <div
                                                        key={item.id}
                                                        style={{
                                                            backgroundColor: highlighted ? "#eee" : "transparent"
                                                        }}
                                                        >
                                                        {item.label}
                                                        </div>
                                                    )}
                                                    wrapperStyle={{
                                                        display: "block"
                                                    }}
                                                    menuStyle={{
                                                        zIndex: "1",
                                                        position: "static",
                                                        borderRadius: "3px",
                                                        boxShadow: "0 2px 12px rgba(0, 0, 0, 0.1)",
                                                        background: "rgba(255, 255, 255, 0.9)",
                                                        padding: "2px 0",
                                                        fontSize: "90%",
                                                        overflow: "auto",
                                                        maxHeight: "50%"
                                                    }}
                                                    inputProps={{ className: "form-control" }}
                                                    value={this.state.address}
                                                    onChange={this.getAddress}
                                                    onSelect={this.SetAddress}
                                                    />
                                                    <HelpBlock>{this.state.addressError}</HelpBlock>
                                                </FormGroup>
                                            </Col>
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Complement</ControlLabel>
                                                    <FormControl className="form-control"
                                                        value={this.state.complement} 
                                                        onChange={(e) => { this.setState({ complement: e.target.value }); }} />
                                                </FormGroup>
                                            </div>
                                        </div>
                                        <div className="row"> 
                                                
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>ZipCode</ControlLabel>
                                                    <FormControl className="form-control"  onChange={(e) => { this.setState({ highWayCodeDate: e.target.value }); }}
                                                        value={this.state.zip} 
                                                        />
                                                </FormGroup>
                                            </div>
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>City</ControlLabel>
                                                    <FormControl className="form-control" value={this.state.city}   onChange={(e) => { this.setState({ city: e.target.value }); }} />
                                                </FormGroup>
                                            </div>
                                        </div>
                                        {this.props.role === "Student"?
                                        <div className="row">
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>Highway Code Date</ControlLabel>
                                                    <FormControl className="form-control"
                                                        type="date"
                                                        value={moment(this.state.highWayCodeDate).format("YYYY-MM-DD")} 
                                                        onChange={(e) => { this.setState({ highWayCodeDate: e.target.value }); }} 
                                                    />
                                                </FormGroup>
                                            </div>
                                            <div className="col-md-6">
                                                <FormGroup>
                                                    <ControlLabel>NEPH number</ControlLabel>
                                                    <FormControl className="form-control" maxLength={12}  onChange={(e) => { this.setState({ highWayCodeDate: e.target.value }); }}
                                                        value={this.state.neph} 
                                                        />
                                                </FormGroup>
                                            </div>
                                        </div>:""}
                                    </div>
                                </div>
                                <div className="clearfix" />
                            </form>
                        </Col>
                        {this.props.role !== "DrivingSchool"?
                        <Row style={{padding:'20px 0px'}}>
                            <Col md={6}>
                            <ControlLabel>
                            Upload front of your ID Card/Passport/Residence permit
                                <span className="text-red">*</span>
                            </ControlLabel>
                            <FormControl
                                type="file"
                                bsClass="form-control"
                                onChange={this.handleFrontFileSelect}
                                accept="image/jpeg,application/pdf"
                                name="frontIDPhoto"
                                id="frontIDPhoto"
                                value={this.state.frontIDPhoto}
                            />
                            {this.state.frontIdPathError!==""?<a href={this.state.frontIdPathError} target="_blank">View current File</a>:""}
                            </Col>
                            <Col md={6}>
                            <ControlLabel>
                            Upload back of your ID Card/Passport/Residence permit
                                <span className="text-red">*</span>
                            </ControlLabel>
                            <FormControl
                                type="file"
                                bsClass="form-control"
                                onChange={this.handleBackFileSelect}
                                accept="image/jpeg,application/pdf"
                                name="backIDPhoto"
                                id="backIDPhoto"
                                value={this.state.backIDPhoto}
                            />
                            {this.state.backIdPathError!==""?<a href={this.state.backIdPathError} target="_blank">View current File</a>:""}
                            </Col>
                        </Row>:""}
                    </Row>
                </Grid>
            </div>
                    </Modal.Body>
                    <Modal.Footer>
                    <Button variant="secondary" onClick={()=>this.setState({showModal:false})}>
                      Close
                    </Button>
                    <Button variant="primary" onClick={this.handleSave} >Update</Button>
                    </Modal.Footer>
                </Modal>
            </div>
        );
    }
}

export default UserCard;
